from fractions import Fraction
from typing import Mapping


def acceptance(mass: Mapping[str, Fraction], accepts: Mapping[str, bool]) -> Fraction:
    return sum((p for x, p in mass.items() if accepts[x]), Fraction(0))


def advantage(real: Mapping[str, Fraction], random: Mapping[str, Fraction],
              accepts: Mapping[str, bool]) -> Fraction:
    return abs(acceptance(real, accepts) - acceptance(random, accepts))


def l1_gap(left: Mapping[str, Fraction], right: Mapping[str, Fraction]) -> Fraction:
    return sum((abs(left[x] - right[x]) for x in left), Fraction(0))


def audit_hop(source_real: Mapping[str, Fraction],
              source_random: Mapping[str, Fraction],
              target_real: Mapping[str, Fraction],
              target_random: Mapping[str, Fraction],
              accepts: Mapping[str, bool]) -> tuple[Fraction, Fraction, Fraction]:
    source_adv = advantage(source_real, source_random, accepts)
    target_adv = advantage(target_real, target_random, accepts)
    upper_bound = (source_adv + l1_gap(target_random, source_random)
                   + l1_gap(target_real, source_real))
    if target_adv > upper_bound:
        raise AssertionError("The additive game-hop bound failed")
    return source_adv, target_adv, upper_bound
